-- composition of rule kernels cte_inlining x projection_pullup (duckdb), template cte_twice
WITH ka AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, [1, 2, 3]::int[] AS c1, ((CASE WHEN REGEXP_MATCHES (((a1.c5 || a1.c5) || a1.c5), '[0-9]{2}') THEN 0.0::numeric ELSE CASE WHEN (FALSE OR CASE WHEN TRUE THEN TRUE ELSE FALSE END) THEN 2.25::numeric ELSE (SELECT MIN (0.0::numeric) FROM rc AS a2) END END % 100) * ((a1.c0)::numeric % 100)) AS c2, LEAST (LEAST (1.5::numeric, (SELECT MAX (100.0::numeric) FROM v0 AS a3 WHERE a1.c1)), NULL::numeric) AS c3 FROM t3 AS a1 WHERE FALSE), kb AS (SELECT a1.c2 AS c0, '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c1, a1.c0 AS c2, '1999-12-31'::date AS c3 FROM t0 AS a1 WHERE NULLIF ((NOT COALESCE (FALSE, (EXISTS (SELECT a1.c0 AS c0)))), TRUE)) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, [1, 2, 3]::int[] AS c1, ((CASE WHEN REGEXP_MATCHES (((a1.c5 || a1.c5) || a1.c5), '[0-9]{2}') THEN 0.0::numeric ELSE CASE WHEN (FALSE OR CASE WHEN TRUE THEN TRUE ELSE FALSE END) THEN 2.25::numeric ELSE (SELECT MIN (0.0::numeric) FROM rc AS a2) END END % 100) * ((a1.c0)::numeric % 100)) AS c2, LEAST (LEAST (1.5::numeric, (SELECT MAX (100.0::numeric) FROM v0 AS a3 WHERE a1.c1)), NULL::numeric) AS c3 FROM t3 AS a1 WHERE FALSE) AS ka) + (SELECT count(*) FROM (SELECT a1.c2 AS c0, '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c1, a1.c0 AS c2, '1999-12-31'::date AS c3 FROM t0 AS a1 WHERE NULLIF ((NOT COALESCE (FALSE, (EXISTS (SELECT a1.c0 AS c0)))), TRUE)) AS kb)
